const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
// Product walkthrough is an illustration, not a live generator or editor.
const studioBody=document.querySelector('.studio-body'),studioTabs=[...document.querySelectorAll('[data-studio]')],studioPlay=document.querySelector('#studio-play'),studioTyped=document.querySelector('#studio-typed');
const studioSteps={generate:{copy:'Prompt → video.'},edit:{copy:'Edit on your timeline.'},publish:{copy:'Ready to share.'}};
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');let studioElapsed=3500,studioLast=0,studioPlaying=false,studioVisible=false,studioCurrent='';
function setStudioView(name){if(studioCurrent===name)return;studioCurrent=name;studioBody.dataset.view=name;studioTabs.forEach(b=>{const yes=b.dataset.studio===name;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});document.querySelector('#studio-panel').setAttribute('aria-labelledby','studio-'+name);document.querySelectorAll('.studio-pane').forEach(p=>p.hidden=!p.classList.contains(name+'-pane'));const step=studioSteps[name];document.querySelector('#studio-step-copy').textContent=step.copy}
function syncStudioControl(){studioPlay.textContent=studioPlaying?'Ⅱ Pause walkthrough':'▶ Play walkthrough';studioPlay.setAttribute('aria-label',studioPlaying?'Pause studio walkthrough':'Play studio walkthrough');studioBody.classList.toggle('walkthrough-paused',!studioPlaying)}
function paintStudio(){const t=studioElapsed%18000;const view=t<6000?'generate':t<12500?'edit':'publish';setStudioView(view);const prompt='Create a cinematic product video for my brand.';studioTyped.textContent=prompt.slice(0,Math.floor(t/48));studioBody.dataset.ready=String(t>2300);document.querySelector('#generation-status').textContent=t<2300?'Describe your idea.':'Ready to edit.'}
function selectStudio(name){studioPlaying=false;studioElapsed={generate:3500,edit:6500,publish:13000}[name];paintStudio();syncStudioControl()}
studioTabs.forEach((b,i)=>{b.addEventListener('click',()=>selectStudio(b.dataset.studio));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%studioTabs.length;if(e.key==='ArrowLeft')n=(i+studioTabs.length-1)%studioTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=studioTabs.length-1;if(n!==undefined){e.preventDefault();studioTabs[n].focus();selectStudio(studioTabs[n].dataset.studio)}})});
studioPlay.addEventListener('click',()=>{studioPlaying=!studioPlaying;syncStudioControl()});new IntersectionObserver(e=>{studioVisible=e[0].isIntersecting},{threshold:.15}).observe(document.querySelector('.studio-app'));
function studioTick(now){if(studioLast&&studioPlaying&&studioVisible&&!document.hidden){studioElapsed+=Math.min(now-studioLast,100);paintStudio()}studioLast=now;requestAnimationFrame(studioTick)}
motionPreference.addEventListener('change',()=>{if(motionPreference.matches){studioPlaying=false;studioElapsed=3500;}paintStudio();syncStudioControl()});if(motionPreference.matches)studioElapsed=3500;paintStudio();syncStudioControl();requestAnimationFrame(studioTick);
